def carry_over(apps, schema_editor):
    """Give existing rows sensible values for the new columns."""
    from datetime import timedelta

    from django.db.models import F
    from django.utils import timezone

    Post = apps.get_model("hub", "Post")
    # Old posts: their activity and "people were told" times are their posting time, so nothing is re-announced.
    Post.objects.update(last_activity_at=F("created_at"), notified_at=F("created_at"))
    recent = timezone.now() - timedelta(days=14)
    Post.objects.filter(is_announcement=True, created_at__gte=recent).update(pinned_at=F("created_at"))
    # Whoever started a group manages it.
    for group in apps.get_model("hub", "Community").objects.exclude(created_by=None):
        group.admins.add(group.created_by_id)


